package com.example.starter.film.exception;

/**
 * 422：请求语义不完整或格式错误（缺段、摘要格式错误、序号越界等），不进行任何写入。
 */
public class UnprocessableException extends RuntimeException {

    public UnprocessableException(String message) {
        super(message);
    }
}

package com.example.starter.film.exception;

/**
 * 409：状态或乐观版本冲突（基于旧版次提交、审核过期、幂等键异参、撤销后再交付等）。
 */
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.film.exception;

/**
 * 404：影片、审核、母版或回执不存在。
 */
public class NotFoundException extends RuntimeException {

    public NotFoundException(String message) {
        super(message);
    }
}

package com.example.starter.film.model;

import java.time.LocalDateTime;

/**
 * 馆藏影片。片段按 {@code plannedSegments} 个序号组成影片。
 *
 * @param id               影片ID
 * @param code             影片编号，业务唯一
 * @param title            影片标题
 * @param plannedSegments  计划片段总数（序号 1..N），无单位
 * @param createdAt        创建时间，Asia/Shanghai
 */
public record Film(
        Long id,
        String code,
        String title,
        int plannedSegments,
        LocalDateTime createdAt
) {
}

package com.example.starter.film.model;

import java.time.LocalDateTime;

/**
 * 片段修复工作版（只追加，永不修改旧记录）。每次提交产生一条新版次行。
 *
 * @param id         行ID
 * @param filmId     所属影片ID
 * @param seq        片段序号，从 1 开始
 * @param versionNo  版次，从 1 开始递增；0 表示“尚无版本”，仅用于提交参数
 * @param digest     内容摘要，4-128 位字母/数字及 {@code . _ : -}
 * @param requestId  提交请求ID（幂等键），全局唯一
 * @param createdAt  提交时间，Asia/Shanghai
 */
public record SegmentVersion(
        Long id,
        Long filmId,
        int seq,
        int versionNo,
        String digest,
        String requestId,
        LocalDateTime createdAt
) {
}

