package com.example.starter.film.model;

import java.time.LocalDateTime;

/**
 * 整片审核请求。创建时按序号固定每段引用的版次（基线），通过时据此生成母版。
 *
 * @param id             审核请求ID
 * @param filmId         所属影片ID
 * @param requestId      审核请求ID（幂等键），全局唯一
 * @param status         审核状态
 * @param masterId       通过后生成的母版ID；未通过或过期为 {@code null}
 * @param createdAt      创建时间，Asia/Shanghai
 * @param decidedAt      决定（通过/撤销）时间；未决定为 {@code null}
 */
public record ReviewRequest(
        Long id,
        Long filmId,
        String requestId,
        ReviewStatus status,
        Long masterId,
        LocalDateTime createdAt,
        LocalDateTime decidedAt
) {
}

package com.example.starter.film.model;

import java.time.LocalDateTime;

/**
 * 不可变固定母版。一旦生成，其引用的各片段版次与摘要快照不再受工作版更新影响。
 *
 * @param id              母版行ID
 * @param masterNo        母版编号，业务唯一且不可变，形如 {@code M-影片编号-审核ID}
 * @param filmId          所属影片ID
 * @param reviewId        来源审核请求ID
 * @param segmentCount    固定时的片段总数
 * @param createdAt       生成时间，Asia/Shanghai
 */
public record Master(
        Long id,
        String masterNo,
        Long filmId,
        Long reviewId,
        int segmentCount,
        LocalDateTime createdAt
) {
}

package com.example.starter.film.model;

/**
 * 母版片段快照：按序号固定该瞬间的版次与摘要。行一经写入永不更新。
 *
 * @param id          行ID
 * @param masterId    所属母版ID
 * @param seq         片段序号，从 1 开始
 * @param versionNo   固定的片段版次
 * @param digest      固定的内容摘要快照
 */
public record MasterSegment(
        Long id,
        Long masterId,
        int seq,
        int versionNo,
        String digest
) {
}

package com.example.starter.film.model;

import java.time.LocalDateTime;

/**
 * 交付回执。保存曾交付的母版快照，审核撤销不删除既有回执；同一交付 requestId 只有一张回执。
 *
 * @param id              行ID
 * @param requestId       交付请求ID（幂等键），全局唯一
 * @param filmId          所属影片ID
 * @param masterId        引用的母版ID
 * @param masterNo        引用的母版编号（冗余快照，便于历史展示）
 * @param snapshotDigest  交付时母版全部片段摘要的定格值，{@code 序号:版次:摘要} 按序号拼接
 * @param createdAt       交付时间，Asia/Shanghai
 */
public record DeliveryReceipt(
        Long id,
        String requestId,
        Long filmId,
        Long masterId,
        String masterNo,
        String snapshotDigest,
        LocalDateTime createdAt
) {
}

package com.example.starter.film.model;

import java.time.LocalDateTime;

/**
 * 审核基线明细：审核请求创建时每个计划片段固定的版次与摘要。
 *
 * @param id          行ID
 * @param reviewId    所属审核请求ID
 * @param seq         片段序号，从 1 开始
 * @param versionNo   固定的片段版次
 * @param digest      固定的内容摘要快照
 * @param fixedAt     固定时间，Asia/Shanghai
 */
public record ReviewSegmentBaseline(
        Long id,
        Long reviewId,
        int seq,
        int versionNo,
        String digest,
        LocalDateTime fixedAt
) {
}

