package com.example.starter.film.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 片段修复提交请求。
 *
 * @param seq           片段序号，从 1 开始
 * @param digest        内容摘要，4-128 位，允许字母数字与 . _ : -
 * @param baseVersion   基于的当前版次；首次提交传 0
 * @param requestId     幂等请求ID，非空，最长 64
 */
public record SegmentSubmitRequest(
        @NotNull @Min(1)
        Integer seq,

        @NotBlank
        @Size(min = 4, max = 128)
        @Pattern(regexp = "[A-Za-z0-9._:\\-]+", message = "摘要格式错误")
        String digest,

        @NotNull @Min(0)
        Integer baseVersion,

        @NotBlank @Size(max = 64)
        String requestId
) {
}

package com.example.starter.film.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 整片审核请求。
 *
 * @param requestId 幂等请求ID，非空，最长 64
 */
public record ReviewRequest(
        @NotBlank @Size(max = 64)
        String requestId
) {
}

package com.example.starter.film.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 交付冻结请求；只引用母版编号，不读取工作版。
 *
 * @param masterNo  审核通过生成的不可变母版编号
 * @param requestId 幂等请求ID，非空，最长 64
 */
public record DeliveryRequest(
        @NotBlank @Size(max = 64)
        String masterNo,

        @NotBlank @Size(max = 64)
        String requestId
) {
}

package com.example.starter.film.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 建档请求：登记一部馆藏影片及其计划片段数。
 *
 * @param code            影片编号，业务唯一，3-64 位字母数字及 . _ : -
 * @param title           影片标题，非空，最长 200
 * @param plannedSegments 计划片段总数，至少 1
 */
public record CreateFilmRequest(
        @NotBlank
        @Size(min = 3, max = 64)
        String code,

        @NotBlank @Size(max = 200)
        String title,

        @NotNull @Min(1)
        Integer plannedSegments
) {
}

