    public List<SegmentVersion> findChainByFilm(long filmId) {
        return jdbc.query(
                "SELECT id, film_id, seq, version_no, digest, request_id, created_at "
                        + "FROM segment_version WHERE film_id = :filmId "
                        + "ORDER BY seq ASC, version_no ASC",
