     * 影片聚合：影片、版次链、审核（含基线）、母版（含快照）、交付回执。
     */
    public record FilmDetail(
            Film film,
            List<SegmentVersion> segmentChain,
            List<ReviewView> reviews,
            List<MasterView> masters,
            List<DeliveryReceipt> deliveries
    ) {
    }
}

